local utils = {}

local function prepare_for_cache(proposals)
    local cache_ready_proposals = {}
    for _, proposal in pairs(proposals) do
      table.insert(cache_ready_proposals, proposal)
    end
    return cache_ready_proposals
end

function utils.send_error(msg, error_message)
    -- TO DO : maybe use msg.reply
    Send(
      {
        Target = msg.From,
        Type = "Error",
        Error = error_message
    })
end

function utils.send_success(msg, data)
    -- TO DO : maybe use msg.reply
    Send(
      {
        Target = msg.From,
        Type = "Success",
        Data = data
    })
end

function utils.update_multisig_cache()
    Send({
        device = 'patch@1.0',
        multisig_info = {
            name = Name,
            signers = Signers,
            proposals = prepare_for_cache(Proposals)
        }
    })
end

function utils.generate_process_id()
    -- TO DO: implement a proper unique ID generator
    return "process_" .. math.random(100000, 999999)
end

function utils.load_multisig_contract(process_id, name, threshold, signers)
    -- TO DO: implement contract loading logic
    -- This is a placeholder function and should be replaced with actual implementation
    print("Loading multisig contract for process_id:", process_id)
end

function utils.is_arweave_address(address)
    if type(address) ~= "string" then
        return false
    end
    -- Arweave addresses are 43 characters long and base64url encoded
    return string.len(address) == 43 and string.match(address, "^[A-Za-z0-9_-]+$") ~= nil
end

return utils
end

package.preload["multisig.lib"] = function(...)
-- Source: /Users/merdikim/multisig/backend/src/multisig/lib.lua
local utils = require "utils.index"
local json = require "json"

local default_settings = {
    threshold = 1, -- Number of signatures required to execute a proposal
    defaultEndTime = 60 * 60 * 24 * 1000, -- Default time (in milliseconds) for a proposal to expire (24 hours)
}

local vote_types = {
    YES = "yes",
    NO = "no",
}

local lib = {}

local function signer_count()
    local count = 0

    for _ in pairs(Signers) do
        count = count + 1
    end

    return count
end

function lib.create_proposal(msg)
    local data = json.decode(msg.Data)

    if not data then
        utils.send_error(msg, "Missing data to create a proposal")
        return
    end

    local from = msg.From
    local description = data.description
    local startTime = data.startTime or msg.Timestamp
    local endTime = data.endTime or (startTime + default_settings.defaultEndTime)
    local signers_total = signer_count()
    --local payload = data.payload -- You can include any additional data you want to associate with the proposal

    if not Signers[from] then
        utils.send_error(msg, "Not allowed to create a proposal. Signer not registered.")
        return
    end

    if not description or description == "" then
        utils.send_error(msg, "Description is required.")
        return
    end

    if endTime <= startTime then
        utils.send_error(msg, "End time must be greater than start time.")
        return
    end

    if endTime <= msg.Timestamp then
        utils.send_error(msg, "End time must be in the future.")
        return
    end

    if signers_total == 0 then
        utils.send_error(msg, "No signers registered.")
        return
    end

    local new_proposal = {
        id = #Proposals + 1,
        description = description,
        startTime = startTime,
        endTime = endTime,
        votes = {},
        executed = false,
        rejected = false,
        threshold = signers_total,
    }

    Proposals[new_proposal.id] = new_proposal

    if signers_total == 1 then
        new_proposal.votes[from] = vote_types.YES -- Automatically vote for the proposal if there's only one signer
        --TODO: execute the proposal immediately since it meets the threshold
    end

    utils.update_multisig_cache()

    utils.send_success(msg, { proposalId = new_proposal.id })
end

function lib.vote(msg)
    local data = json.decode(msg.Data)

    if not data then
        utils.send_error(msg, "Missing data to vote")
        return
    end

    local from = msg.From
    local proposalId = data.proposalId
    local vote = data.vote

    if not Signers[from] then
        utils.send_error(msg, "Not allowed to vote. Signer not registered.")
        return
    end

    local proposal = Proposals[proposalId]
    if not proposal then
        utils.send_error(msg, "Proposal not found.")
        return
    end

    if proposal.executed or proposal.rejected then
        utils.send_error(msg, "Proposal already executed or rejected.")
        return
    end

    if msg.Timestamp > proposal.endTime then
        utils.send_error(msg, "Proposal has expired.")
        return
    end

    if proposal.votes[from] then
        utils.send_error(msg, "Address has already voted on this proposal.")
        return
    end

    if vote ~= vote_types.YES and vote ~= vote_types.NO then
        utils.send_error(msg, "Invalid vote type. Use 'yes' or 'no'.")
        return
    end

    proposal.votes[from] = vote

    -- Check if the proposal can be executed based on the votes and threshold
    local yesVotes = 0
    local noVotes = 0
    for _, v in pairs(proposal.votes) do
        if v == vote_types.YES then
            yesVotes = yesVotes + 1
        elseif v == vote_types.NO then
            noVotes = noVotes + 1
        end
    end

    if yesVotes >= proposal.threshold then
        --TO DO: execute the proposal since it meets the threshold
    end

    if noVotes > signer_count() - proposal.threshold then
        proposal.rejected = true -- Mark the proposal as rejected since no amount of yes votes can reach the threshold
    end

    utils.update_multisig_cache()
    utils.send_success(msg, { message = "Vote recorded." })
end

function lib.get_proposal(msg)
    local data = msg.Data
    local proposalId = data.proposalId

    local proposal = Proposals[proposalId]
    if not proposal then
        utils.send_error(msg, "Proposal not found.")
        return
    end

    utils.send_success(msg, { proposal = proposal })
end

function lib.add_signer(msg)
    local data = json.decode(msg.Data)

    if not data then
        utils.send_error(msg, "Missing data to add signer")
        return
    end

    local new_signer = data.address

    if not Signers[msg.From] then
        utils.send_error(msg, "Not allowed to add signer. Signer not registered.")
        return
    end

    if not utils.is_arweave_address(new_signer) then
        utils.send_error(msg, "Valid signer address is required.")
        return
    end

    if Signers[new_signer] then
        utils.send_error(msg, "Signer already registered.")
        return
    end

    Signers[new_signer] = 1

    utils.update_multisig_cache()
    utils.send_success(msg, { message = "Signer registered successfully." })
end

function lib.remove_signer(msg)
    local from = msg.From
    local data = json.decode(msg.Data)

    if not data then
        utils.send_error(msg, "Missing data to remove signer")
        return
    end

    local signer_to_remove = data.address

    if not Signers[from] then
        utils.send_error(msg, "Not allowed to remove signer. Signer not registered.")
        return
    end

    if not utils.is_arweave_address(signer_to_remove) then
        utils.send_error(msg, "Valid signer address is required.")
        return
    end

    if not Signers[signer_to_remove] then
        utils.send_error(msg, "Signer not registered.")
        return
    end

    if signer_count() <= 1 then
        utils.send_error(msg, "Cannot remove the last signer.")
        return
    end

    Signers[signer_to_remove] = nil

    utils.update_multisig_cache()
    utils.send_success(msg, { message = "Signer unregistered successfully." })
end

return lib
end

